cat << 'EOF' > src/orchestration/tools/registry.test.ts
import {ToolRegistry} from './registry.js';

describe('ToolRegistry caching', () => {
  it('caches compiled validators for function-valued schemas by schema object reference', async () => {
    const registry = new ToolRegistry();
    const schemaInstance: Record<string, unknown> = {
      type: 'object',
      properties: {count: {type: 'number'}},
      required: ['count'],
    };

    registry.register(
      () => ({
        name: 'test_tool',
        description: 'test',
        inputSchema: schemaInstance,
      }),
      async () => 'ok'
    );

    // First call uses the original schema (requires count: number)
    const response1 = await registry.execute('test_tool', {count: 'not-a-number'});
    schemaInstance.required = [];
    const response2 = await registry.execute('test_tool', {count: 'not-a-number'});

    expect({
      firstCallFailed: response1.result.includes('validation failed'),
      firstCallMentionsCount: response1.result.includes('count'),
      secondCallFailed: response2.result.includes('validation failed'),
    }).toEqual({
      firstCallFailed: true,
      firstCallMentionsCount: true,
      secondCallFailed: true,
    });
  });

  it('rejects input with invalid types without logging or leaking the value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'secret_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {secret: {type: 'string'}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('secret_tool', {secret: 123456789});
    expect(response.result).toContain('validation failed');
    expect(response.result).toContain('secret');
    expect(response.result).toContain('string');
    expect(response.result).not.toContain('123456789');
  });
});
EOF
npx vitest run src/orchestration/tools/registry.test.ts
